WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT e.id, e.nome, e.email, e.cargo, e.ativo, (SELECT count(*) FROM pedidos p WHERE p.executivo_id = e.id) AS pedidos FROM executivos e JOIN eu ON (eu.admin OR e.id = eu.executivo_id) ORDER BY e.ativo DESC, e.nome LIMIT 500
